// Class 7 Social Science practice bank, part 4: Geographical Diversity of India to The Constitution of India. Extra questions for year-long practice (unreviewed draft).
(function () {
  let n = 4 - 1;
  // M(level, question, right answer, three wrong answers, explanation): the right answer is stored at a varying position.
  function M(level, q, right, wrong, explain) {
    const at = (n++) % 4;
    const options = wrong.slice();
    options.splice(at, 0, right);
    return { q, options, answer: at, explain, level };
  }
  function W(marks, q, a, type) {
    const o = { q, a, marks };
    if (type) o.type = type;
    return o;
  }
  StudyData.addPractice(7, "sst", {
  "geographical-diversity-of-india": {
    mcq: [
      M(1, "In the lesson, Mount Everest is described as lying in", "Nepal", ["India", "Bhutan", "Sri Lanka"], "Kanchenjunga is India's highest peak, while Mount Everest is described as lying in Nepal."),
      M(1, "The Andaman and Nicobar Islands lie in the", "Bay of Bengal", ["Arabian Sea", "Palk Strait", "Red Sea"], "They are in the Bay of Bengal, while Lakshadweep is in the Arabian Sea."),
      M(1, "Which Himalayan range is called the 'lesser' range?", "Himachal", ["Himadri", "Shiwaliks", "Kanchenjunga"], "Himadri is the greater range, Himachal the lesser and the Shiwaliks the outer range."),
      M(1, "Coral islands are formed from the skeletons of tiny sea creatures called", "corals", ["sponges", "starfish", "snails"], "Lakshadweep is made of coral."),
      M(1, "The Western Ghats lie along which edge of the Peninsular Plateau?", "The western edge", ["The eastern edge", "The northern edge", "The middle"], "The Western Ghats are on the western edge and the Eastern Ghats on the eastern edge."),
      M(1, "Hill ranges along the western and eastern edges of the Peninsular Plateau are called the", "Ghats", ["Shiwaliks", "Dunes", "Alluvium"], "The Ghats are hill ranges on the edges of the Peninsular Plateau."),
      M(1, "The Himalayas stretch across the north of India from", "west to east", ["north to south", "east to south", "south to west"], "The Himalayas stretch from west to east."),
      M(2, "Which of these is a role of the Himalayas in India's geography?", "They are a source of rivers", ["They are a source of coral", "They are a belt of sand dunes", "They are a sea route"], "The Himalayas act as a barrier and a source of rivers."),
      M(2, "Which of these is NOT something that landforms affect, according to the lesson?", "The number of days in a year", ["Climate", "Farming", "Travel and trade"], "Landforms affect climate, farming, settlement, travel and trade."),
      M(2, "A table of regions lists: P – sand dunes and little rain; Q – fertile alluvium; R – coral islands; S – old hard rock with hills on its edges. Which one is the Peninsular Plateau?", "S", ["P", "Q", "R"], "The Peninsular Plateau is an old hard-rock region with the Ghats on its edges."),
      M(2, "Yearly rainfall of three regions is: A – 10 cm, B – 150 cm, C – 40 cm. Which is most likely the Thar Desert?", "A", ["B", "C", "All three"], "The Thar gets very little rain, so the region with the lowest rainfall fits it."),
      M(2, "A river flows from the Himalayas across the plains to the sea. Which two regions does it cross first?", "The Himalayas and the Northern Plains", ["The Thar and the Ghats", "The Plateau and the islands", "The coasts and the Thar"], "Rivers begin in the Himalayas and flow over the Northern Plains."),
      M(2, "A traveller goes inland from the Arabian Sea coast and begins to climb steeply. Which range does she meet first?", "The Western Ghats", ["The Eastern Ghats", "The Shiwaliks", "The Himadri"], "The Western Coastal Plain lies between the Arabian Sea and the Western Ghats."),
      M(2, "Compared with the Himalayas, the Peninsular Plateau is", "much older", ["much younger", "just as young", "newly folded"], "The Himalayas are young fold mountains, while the Plateau is an old, hard rock region."),
      M(2, "Which one does NOT belong with the others?", "Shiwaliks", ["Western Ghats", "Eastern Ghats", "Peninsular Plateau edge"], "The Shiwaliks are part of the Himalayas, not the Plateau's edges."),
      M(2, "Why are roads and railways easier to build on the Northern Plains than in the Himalayas?", "The land is flat", ["The land is steeper", "There are no towns", "There is no soil"], "Flat land makes building and travel easier."),
      M(2, "Which pair of island group and sea is correct?", "Lakshadweep – Arabian Sea", ["Lakshadweep – Bay of Bengal", "Andaman and Nicobar – Arabian Sea", "Nicobar – Palk Strait"], "Lakshadweep is in the Arabian Sea; the Andaman and Nicobar Islands are in the Bay of Bengal."),
      M(2, "Which match is WRONG?", "Thar Desert – heavy rainfall", ["Northern Plains – fertile alluvium", "Himalayas – source of rivers", "Lakshadweep – coral islands"], "The Thar gets very little rain."),
      M(2, "Heavy rain and melting snow swell rivers in the Himalayas. Which region will most probably receive the flood water first?", "The Northern Plains", ["The Thar Desert", "Lakshadweep", "The Eastern Ghats"], "Rivers flow down from the Himalayas into the Northern Plains."),
      M(3, "From the Arabian Sea going east, which is the correct order?", "Western Coastal Plain, Western Ghats, Peninsular Plateau", ["Western Ghats, Western Coastal Plain, Peninsular Plateau", "Peninsular Plateau, Western Ghats, Western Coastal Plain", "Western Coastal Plain, Peninsular Plateau, Western Ghats"], "The coastal plain lies between the sea and the Ghats, and the Plateau lies beyond."),
      M(3, "Which statement is NOT correct?", "The Shiwaliks are the highest Himalayan range", ["Kanchenjunga is India's highest peak", "The Thar lies in the north-west", "The Eastern Coastal Plain lies along the Bay of Bengal"], "The Himadri is the highest range; the Shiwaliks are the outer and lowest."),
      M(3, "A stream starts near Kanchenjunga's snow and flows south to the plains. Which Himalayan range does it cross LAST?", "The Shiwaliks", ["The Himadri", "The Himachal", "The Eastern Ghats"], "Going south the ranges are the Himadri, the Himachal and then the Shiwaliks."),
      M(3, "Which two regions are separated by the Western Ghats?", "The Western Coastal Plain and the interior plateau", ["The Thar and the Northern Plains", "The Himalayas and the plains", "Lakshadweep and the Andamans"], "The Western Ghats lie between the narrow coast and the Peninsular Plateau."),
      M(3, "Population per sq km is: P – 50 (sand dunes), Q – 800 (fertile river plain), R – 100 (steep hills). Which is most likely the Northern Plains?", "Q", ["P", "R", "None of them"], "Fertile, flat river plains support many people."),
    ],
    written: [
      W(1, "State one difference between the Himadri and the Shiwaliks.", "The Himadri is the greater and highest range.\nThe Shiwaliks are the outer and lowest range.", "short"),
      W(2, "How does alluvium help the people of the Northern Plains?", "Alluvium is fertile soil deposited by rivers.\nIt makes the land good for farming, so many people live and farm there.", "short"),
      W(2, "Write two uses of the Himalayas to India.", "They act as a barrier in the north.\nThey are the source of rivers such as the Ganga and the Brahmaputra.", "short"),
      W(2, "Name the seas on the two sides of the Peninsular Plateau and the coastal plain beside each.", "The Arabian Sea lies in the west, beside the Western Coastal Plain.\nThe Bay of Bengal lies in the east, beside the Eastern Coastal Plain.", "short"),
      W(2, "Why is the Thar Desert thinly populated?", "It gets very little rain and has sand dunes.\nWater is scarce, so farming and settlement are difficult.", "short"),
      W(2, "Name the two island groups of India and the seas they lie in.", "Lakshadweep lies in the Arabian Sea.\nThe Andaman and Nicobar Islands lie in the Bay of Bengal.", "short"),
      W(3, "Name the three ranges of the Himalayas from the highest to the lowest and mention one fact about each.", "Himadri – the greater, highest range.\nHimachal – the lesser range.\nShiwaliks – the outer, lowest range.", "short"),
      W(4, "Describe the Peninsular Plateau and its edges.", "The Peninsular Plateau is an old, hard-rock region.\nThe Western Ghats lie on its western edge and the Eastern Ghats on its eastern edge.\nThe Western Coastal Plain lies between the Western Ghats and the Arabian Sea; the Eastern Coastal Plain lies along the Bay of Bengal and is wider.", "long"),
      W(5, "Explain how the landforms of India affect the lives of people. Give examples from the mountains, plains and desert.", "Landforms affect climate, farming, settlement, travel and trade.\nThe Himalayas act as a barrier and are the source of rivers.\nThe Northern Plains are flat and fertile because of alluvium, so many people live and farm there.\nThe Thar Desert gets very little rain, so few people live there.\nCoasts support fishing, ports and trade.", "long"),
      W(4, "Case study: Arjun travels from Punjab to Kerala. He crosses fertile flat farmland, then a high raised area with hills on its western edge, and finally reaches a narrow strip of land beside the sea.\n(i) Name the first region he crosses.\n(ii) Name the hills on the western edge.\n(iii) Name the narrow coast and the sea beside it.", "(i) The Northern Plains.\n(ii) The Western Ghats, on the edge of the Peninsular Plateau.\n(iii) The Western Coastal Plain, beside the Arabian Sea.", "case"),
    ]
  },
  "understanding-the-weather": {
    mcq: [
      M(1, "Which instrument is used to measure temperature?", "Thermometer", ["Barometer", "Anemometer", "Rain gauge"], "A thermometer measures temperature. A barometer measures air pressure."),
      M(1, "High pressure forms where the air is", "cool and sinking", ["warm and rising", "moist and rising", "very hot"], "Cool air is heavier and sinks, creating high pressure."),
      M(1, "Which of these is NOT a form of precipitation?", "Wind", ["Hail", "Snow", "Sleet"], "Precipitation is water falling from clouds as rain, snow, sleet or hail."),
      M(1, "Weather at a place can change from", "hour to hour", ["century to century", "decade to decade", "age to age"], "Weather is the state of the atmosphere at a particular time."),
      M(1, "Water falling from clouds as rain, snow, sleet or hail is called", "precipitation", ["condensation", "humidity", "pressure"], "Precipitation is water falling from clouds."),
      M(1, "To decide whether to carry an umbrella, you would check the forecast for", "precipitation", ["air pressure", "wind speed", "altitude"], "Rain is a form of precipitation."),
      M(1, "Orographic rain is also called", "relief rain", ["cyclone rain", "dew rain", "frost rain"], "Rain that falls when air is forced up a mountain slope is called orographic or relief rain."),
      M(2, "The three types of rain named in the lesson differ in", "how the moist air is forced to rise", ["the colour of the clouds at the time", "only the season in which rain falls", "only how fast the wind blows"], "Rain can be convectional, orographic or cyclonic, depending on how the air is forced to rise."),
      M(2, "On a very hot day the air can hold", "more water vapour", ["less water vapour", "no water vapour", "the same vapour as a cold day"], "Warm air can hold more vapour."),
      M(2, "A flag on a pole streams out towards the north. The wind is blowing from the", "south", ["north", "east", "west"], "Winds are named after the direction they blow from, and this wind blows towards the north."),
      M(2, "A wind from the north-west blows towards the", "south-east", ["north-east", "south-west", "north-west"], "Winds blow towards the opposite direction from which they come."),
      M(2, "Four days of readings are 30 °C, 31 °C, 29 °C and 30 °C. These readings describe the", "weather of those days", ["climate of the country", "monsoon of the year", "pressure of the sea"], "Day-to-day conditions are weather. Climate is the average over many years."),
      M(2, "Which statement describes climate rather than weather?", "Delhi is hot and dry in summer each year", ["It rained in Delhi at noon on Tuesday", "Tonight is much cooler than last night", "A storm hit the coast early this morning"], "Climate is the average weather of a place over a long period."),
      M(2, "Which instrument and element are NOT correctly paired?", "Barometer – wind speed", ["Thermometer – temperature", "Rain gauge – rainfall", "Hygrometer – humidity"], "A barometer measures air pressure; wind speed is measured by an anemometer."),
      M(2, "What makes the wind blow?", "Difference in air pressure", ["The colour of the sky", "The sound of thunder", "The ripples in a river"], "Wind is air moving from a high-pressure area to a low-pressure area."),
      M(2, "Which of these changes into tiny droplets when rising air cools?", "Water vapour", ["Smoke from fires", "Dust from the soil", "Salt from the sea"], "Water vapour condenses into tiny droplets, which form clouds."),
      M(1, "Air moves INTO an area of", "low pressure", ["high pressure", "no pressure", "equal pressure everywhere"], "Wind blows from high pressure to low pressure."),
      M(2, "Which statement is NOT true?", "Weather hardly ever changes", ["Weather can change within hours", "Climate is a long-term average", "Wind is air in motion"], "Weather changes often, even from hour to hour."),
      M(2, "Which of these is an element of weather?", "Wind", ["Latitude", "Soil", "Population"], "The elements are temperature, air pressure, wind, humidity and precipitation."),
      M(2, "Warm air rising from heated ground builds tall clouds and gives afternoon showers. This type of rain is", "convectional", ["orographic", "cyclonic", "polar"], "Convectional rain comes from air that is heated and rises."),
      M(3, "During a hot day, pressure over the land is lower than over the sea. The wind will blow from", "the sea to the land", ["the land to the sea", "nowhere, since there is no wind", "the sky to the sea"], "Wind blows from high pressure to low pressure."),
      M(3, "A place has a rainy day but a dry climate. How can this be?", "Weather is one day; climate is the long average", ["Weather and climate are exactly the same thing", "Climate changes completely every single hour", "A dry climate means rain can never fall"], "Weather is the condition at a time, while climate is the average over many years."),
      M(3, "In a month, rain fell on 3 days only. A student says 'the climate is rainy'. What is wrong?", "A month's data show weather, not climate", ["Rain is not counted as an element of weather", "Climate is always measured in hours, not years", "Three days of rain are too many for a month"], "Climate needs the average over many years."),
      M(3, "The order of steps that lead to rain is", "heating, rising, cooling, condensation, rain", ["rain, cooling, heating, rising, condensation", "condensation, rain, heating, cooling, rising", "cooling, heating, rain, rising, condensation"], "Air heats and rises, cools, its vapour condenses into droplets and clouds, and then rain falls."),
      M(2, "Air at place P is sinking and at place Q is rising. Where is pressure higher?", "At P", ["At Q", "At both equally", "At neither"], "Sinking cool air creates high pressure and rising warm air creates low pressure."),
      M(3, "Hot dry air in a desert holds less moisture than warm air over the sea. So the desert has", "lower humidity", ["higher humidity", "more rain clouds", "heavier fog"], "Humidity is the water vapour in the air; deserts have little."),
    ],
    written: [
      W(1, "What is weather?", "Weather is the state of the atmosphere at a place at a particular time. It can change from hour to hour.", "short"),
      W(1, "Name the five main elements of weather.", "Temperature, air pressure, wind, humidity and precipitation.", "short"),
      W(2, "Match the instrument to what it measures: thermometer, barometer, anemometer.", "Thermometer – temperature.\nBarometer – air pressure.\nAnemometer – wind speed.", "short"),
      W(2, "How do warm air and cool air produce wind?", "Warm air is lighter and rises, creating low pressure.\nCool air is heavier and sinks, creating high pressure.\nAir then moves from the high-pressure area to the low-pressure area, which is wind.", "short"),
      W(2, "Why are winds named after the direction they blow from? Give an example.", "This tells us where the wind comes from.\nFor example, a south-west wind blows from the south-west.", "short"),
      W(2, "Name the three types of rain.", "Convectional, orographic (relief) and cyclonic rain. They differ in how the air is forced to rise.", "short"),
      W(3, "Describe how a cloud forms.", "Moist air rises and cools.\nThe water vapour condenses into tiny droplets.\nThese droplets gather to form clouds.", "short"),
      W(4, "Write the instrument used to measure each of these: temperature, rainfall, wind speed, humidity and air pressure.", "Temperature – thermometer.\nRainfall – rain gauge.\nWind speed – anemometer.\nHumidity – hygrometer.\nAir pressure – barometer.", "long"),
      W(5, "Explain how rain is formed, starting from the heating of the air.", "The sun heats the air or land and warm air rises, creating low pressure.\nAs it rises it cools, and the water vapour condenses into tiny droplets that form clouds.\nWhen the droplets join and become heavy, water falls as precipitation (rain).\nRain may be convectional, orographic or cyclonic depending on how the air is forced to rise.", "long"),
      W(4, "Case study: On Monday a school's weather record shows: temperature 34 °C, humidity high, wind from the south-west, and a thunderstorm in the evening.\n(i) List two weather elements recorded.\n(ii) In which direction is the air moving?\n(iii) Why can this record not tell us the climate?", "(i) Any two: temperature, humidity, wind, precipitation.\n(ii) Towards the north-east.\n(iii) It covers only one day; climate is the average over many years.", "case"),
    ]
  },
  "climates-of-india": {
    mcq: [
      M(1, "How many seasons does the lesson describe for India?", "Four", ["Two", "Three", "Six"], "Summer, the south-west monsoon season, the retreating monsoon and winter."),
      M(1, "Which season follows the south-west monsoon season?", "Retreating monsoon", ["Winter season in the plains", "Summer in the north", "A second rainy season"], "The retreating monsoon (October–November) follows, and then winter."),
      M(1, "Of two places, one near the equator and one far from it, which is usually hotter?", "The one near the equator", ["The one far from it", "Both are always equal", "It depends on the sound of wind"], "Places near the equator are hotter."),
      M(1, "Which of these is NOT a factor that affects India's climate?", "Colour of the soil", ["Latitude", "Altitude", "Distance from the sea"], "The factors are latitude, altitude, distance from the sea, relief and monsoon winds."),
      M(1, "The winter season of India is mostly", "cool and dry", ["hot and dry", "warm and rainy", "cool and rainy"], "Winter (December to February) is cool and dry."),
      M(1, "April falls in which season?", "Summer", ["Winter", "South-west monsoon", "Retreating monsoon"], "Summer is March to May."),
      M(1, "'Retreating monsoon' means that the monsoon is", "withdrawing from India", ["arriving in Kerala", "at its heaviest", "not yet begun"], "In October–November the monsoon withdraws from India."),
      M(2, "The south-west monsoon spreads over the whole country by about", "July", ["March", "October", "January"], "It reaches Kerala around the start of June and spreads over the country by about July."),
      M(2, "Which place is likely to have the biggest difference between summer and winter temperatures?", "An inland town far from the sea", ["A town right on the sea coast", "A small island in the sea", "A port beside the open sea"], "Inland places have extremes, while coastal places have a mild climate."),
      M(2, "Temperatures in January and May are: Town A – 14 °C and 40 °C; Town B – 24 °C and 31 °C. Which is more likely to be near the sea?", "Town B", ["Town A", "Both equally", "Neither"], "Coastal places have a mild climate, with a small difference between seasons."),
      M(2, "Too much rain in a short time may cause", "floods", ["droughts", "loo", "snowfall in plains"], "Too little rain causes drought and too much causes floods."),
      M(2, "Farmers in Kerala see heavy rain begin in early June. This shows the", "arrival of the south-west monsoon", ["beginning of the winter season", "end of the summer-season rain", "retreating monsoon withdrawing"], "The south-west monsoon arrives around the start of June in Kerala."),
      M(2, "Monthly rainfall at a place is: March – 1 cm, June – 19 cm, July – 31 cm, December – 1 cm. The heaviest rain falls in", "the south-west monsoon season", ["the hot and dry summer season", "the cool and dry winter season", "the retreating monsoon season"], "June and July fall in the south-west monsoon season (June to September)."),
      M(2, "In summer the south-west monsoon winds blow mainly", "from the sea towards the land", ["from the land towards the sea", "only along the mountains", "from the Himalayas southwards"], "They bring moisture from the sea and cause most of India's rain."),
      M(2, "'Relief' as a factor of climate refers to", "mountains and the height of land", ["the distance from the equator", "the winds that blow from the sea", "the nearness to the north pole"], "Relief (mountains) is one factor that shapes India's climate."),
      M(2, "Mumbai on the coast is milder than Nagpur inland mainly because of", "distance from the sea", ["latitude alone", "the loo", "western disturbances"], "Coastal places have a mild climate, and inland places have extremes."),
      M(2, "Which pair of factor and meaning is correct?", "Latitude – distance from the equator", ["Altitude – distance from the sea", "Relief – nearness to the poles", "Monsoon – height above sea level"], "Latitude shows how far a place is from the equator; altitude is height above sea level."),
      M(1, "Which month marks the end of the south-west monsoon season?", "September", ["June", "December", "March"], "The season runs from June to September."),
      M(2, "Which two months belong to DIFFERENT seasons?", "February and March", ["June and July", "April and May", "December and January"], "February is in winter and March begins summer."),
      M(2, "Which season comes right after winter?", "Summer", ["South-west monsoon season", "Retreating monsoon season", "A second winter season"], "Winter (December to February) is followed by summer (March to May)."),
      M(3, "A town has 45 °C in May, 4 °C in December and most of its rain in July and August. Where is it most likely to be?", "Inland in north India", ["On the Kerala coast", "On a small island", "In the Lakshadweep"], "Extreme heat and cold with rain only in the monsoon fits an inland northern place."),
      M(3, "Which statement is correct?", "The Himalayas block cold winds; monsoon brings rain", ["The Himalayas bring the hot loo into the plains", "Monsoon winds blow the same way throughout the year", "The retreating monsoon is India's rainiest season"], "The Himalayas block cold northern winds and the south-west monsoon gives most rain."),
      M(3, "If the monsoon reaches Kerala about 1 June and covers India by about July, it takes roughly", "one month", ["one week", "one year", "six months"], "From the start of June to about July is roughly a month."),
      M(2, "Which season has NO month from June to September?", "Winter", ["South-west monsoon", "Both seasons have some", "Every season"], "Winter is December to February."),
      M(3, "A weak monsoon one year leaves rivers low and fields dry. The most likely effect is on", "farming", ["the shape of the Himalayas", "the length of the day", "the position of the equator"], "The monsoon is vital for farming, and too little rain causes drought."),
      M(3, "A hill town in Himachal is cool in June while the plains below are hot. This is best explained by", "altitude", ["distance from the equator only", "the retreating monsoon", "the loo"], "Temperature falls as altitude rises."),
    ],
    written: [
      W(2, "Which season is the hottest and which the coolest in the plains of north India? Give their months.", "Summer is the hottest season (March to May).\nWinter is the coolest season (December to February).", "short"),
      W(2, "What are western disturbances? When do they bring rain?", "They bring some rain to north-western India.\nThis rain falls in winter.", "short"),
      W(2, "Give the months of the four seasons.", "Summer: March to May.\nSouth-west monsoon: June to September.\nRetreating monsoon: October–November.\nWinter: December to February.", "short"),
      W(2, "List the five factors that affect India's climate.", "Latitude, altitude, distance from the sea, relief (mountains) and monsoon winds.", "short"),
      W(2, "Why is a hill station cooler than a plain town?", "Temperature falls as altitude increases.\nA hill station is at a greater height above sea level.", "short"),
      W(2, "What is the retreating monsoon?", "It is the period in October–November when the monsoon withdraws from India.", "short"),
      W(3, "Write two ways in which the monsoon is a problem when it is too weak or too strong.", "If rain is too little, there is drought and crops dry up.\nIf rain is too much, there are floods that damage fields and homes.", "short"),
      W(4, "Describe each of the four seasons of India in one line.", "Summer (March to May) is hot and dry, with the loo in the north.\nThe south-west monsoon season (June to September) brings most of the rain.\nThe retreating monsoon (October–November) is when the monsoon withdraws.\nWinter (December to February) is cool and dry.", "long"),
      W(5, "Describe the south-west monsoon: its arrival, its importance and its problems.", "Monsoon winds reverse direction with the seasons, and the south-west monsoon gives India most of its rain.\nIt arrives in Kerala around the start of June and spreads over the country by about July.\nIt is vital for farming.\nToo little rain causes drought and too much causes floods.", "long"),
      W(4, "Case study: Kavita lives in a coastal town and her cousin Ritu lives inland in a northern town. In May Ritu's town is very hot with a dry wind in the afternoon, while Kavita's town is warm but humid. In December Ritu's town is much colder.\n(i) Name the hot dry wind in Ritu's town.\n(ii) Why is Kavita's town milder?\n(iii) In which season does Ritu's town get some winter rain?", "(i) The loo.\n(ii) It is near the sea, and coastal places have a mild climate.\n(iii) In winter, some rain in north-western India comes from western disturbances.", "case"),
    ]
  },
  "new-beginnings-cities-and-states": {
    mcq: [
      M(1, "The word 'Mahajanapada' means", "a great realm", ["a small village", "a silver coin", "a trade route"], "Mahajanapadas were large states, called 'great realms'."),
      M(1, "Another name for a gana is a", "sangha", ["fort", "mint", "granary"], "Ganas, or sanghas, were ruled by a group of leaders."),
      M(1, "Early punch-marked coins were usually made of", "silver", ["paper", "wood", "clay"], "Punch-marked coins were usually of silver, with symbols punched on them."),
      M(1, "Money or goods that a ruler collects from people is a", "tax", ["coin", "gift", "fine"], "Kings collected taxes to pay for armies and forts."),
      M(1, "Towns of the 6th century BCE grew mainly in the plains of the river", "Ganga", ["Kaveri", "Narmada", "Godavari"], "Many towns grew in the Ganga plains."),
      M(1, "Which animals found in Magadha's forests were useful to its rulers?", "Elephants", ["Camels", "Yaks", "Horses of the sea"], "Magadha had forests with elephants."),
      M(1, "What protected the capitals of kings in this period?", "Forts", ["Terraces", "Granaries", "Seals"], "Kings kept armies, and forts protected the capitals."),
      M(2, "Which period came first?", "The 6th century BCE", ["The 4th century BCE", "The 2nd century BCE", "The 1st century CE"], "BCE centuries count backwards, so the 6th century BCE is the earliest."),
      M(2, "State P is run by one king whose son will rule after him. State Q is run by a group of leaders who decide together. Which is a gana?", "State Q", ["State P", "Both of them", "Neither of them"], "In a gana, a group of leaders took decisions together."),
      M(2, "Why did kings of this time collect taxes?", "To pay for armies and forts", ["To build new mountains for defence", "To grow more iron ore in the fields", "To print paper money for traders"], "Kings collected taxes and kept armies, and forts protected the capitals."),
      M(2, "How did coins make exchange easier?", "Goods could be bought without barter", ["All goods came to cost the same price", "People were stopped from trading anywhere", "Coins were heavier to carry than goods"], "Coins were accepted in many places, so people did not need a double coincidence of wants."),
      M(1, "River routes helped Magadha because they", "made trade easy", ["stopped farming", "kept armies away", "dried the fertile land"], "Magadha had river routes for trade."),
      M(2, "Fertile land helped Magadha become strong because it gave", "plenty of food for a bigger population", ["very little farm produce for the people", "a smaller number of people to support", "a lower amount of tax for the king"], "Fertile land produced more food, which supported more people and the army."),
      M(2, "Both Mahajanapadas ruled by kings and those ruled by groups of leaders had", "rulers who took decisions for the state", ["no rulers or leaders of any kind", "no use of iron tools in their lands", "no towns, forts or taxes at all"], "Some states had a king (monarchy) and some a group of leaders (gana)."),
      M(2, "The Vajji sangha is an example of a", "gana (republic)", ["monarchy", "dynasty", "empire"], "The Vajji sangha, with its centre at Vaishali, was ruled by a group of leaders."),
      M(2, "Which resource of Magadha helped to make strong weapons and tools?", "Iron ore mines", ["Coral reefs", "Snow fields", "Salt lakes"], "Magadha had iron ore mines, which helped it make iron tools and weapons."),
      M(2, "The Mauryan empire began about 321 BCE. The Mahajanapadas arose in the 6th century BCE. Which came first?", "The Mahajanapadas", ["The Mauryan empire", "They began together", "Neither can be dated"], "The 6th century BCE is earlier than 321 BCE."),
      M(2, "Which statement about early Indian states is correct?", "Some had kings and some had groups of leaders", ["Every one of them was ruled by a single king", "Every one of them was ruled by a group of leaders", "None of them collected taxes from the people"], "States were either monarchies or ganas."),
      M(3, "Why did Magadha, rather than the Vajji sangha, become the most powerful?", "Rich land, iron ore and able rulers", ["It stayed isolated from all trade routes", "It was ruled by a council of leaders", "Its rivers dried up during every summer"], "Fertile land, iron ore, forests, river routes and rulers such as Bimbisara and Ajatashatru made Magadha strong."),
      M(3, "A historian says 'Texts mention sixteen Mahajanapadas'. What should she remember when using only texts?", "A text may be one-sided or biased", ["Texts are always complete and exact", "Texts can replace all other sources", "Texts cannot be old or ancient"], "Historians check who wrote a source and why, and also use other evidence such as coins."),
      M(2, "Which factor does NOT help explain the rise of cities in the Ganga plains?", "A lack of iron tools", ["Farming", "Trade", "Use of iron tools"], "Iron tools, farming and trade helped towns grow."),
      M(3, "Which list shows the capitals of Magadha in order?", "Rajagriha, then Pataliputra", ["Pataliputra, then Rajagriha", "Vaishali, then Pataliputra", "Rajagriha, then Vaishali"], "Rajagriha was the first capital and Pataliputra the later one."),
      M(3, "An archaeologist digs up silver coins stamped with symbols in a Ganga plain town. This suggests that the town", "took part in trade", ["had no markets", "had no towns", "used only barter"], "Punch-marked coins made exchange easier, so they point to trade."),
      M(3, "In which state did a group of leaders decide matters together instead of a king?", "In a gana such as the Vajji sangha", ["In Magadha under Bimbisara", "In a state ruled by a king's son", "In Pataliputra under Ajatashatru"], "Ganas were states ruled by a group of leaders."),
      M(2, "How did forts help rulers?", "They protected the capitals", ["They were used to collect taxes", "They were where coins were made", "They were fields for growing crops"], "Forts protected the capitals."),
    ],
    written: [
      W(2, "Why did towns grow in the Ganga plains from about the 6th century BCE? Give two reasons.", "Farming and the use of iron tools produced more food.\nTrade and the use of punch-marked coins made exchange easier.", "short"),
      W(1, "Name two rulers of Magadha.", "Bimbisara and Ajatashatru.", "short"),
      W(2, "What were punch-marked coins? Why were they important?", "They were early coins, usually of silver, with symbols punched on them.\nThey made exchange easier than barter.", "short"),
      W(3, "State two features of a monarchy and two features of a gana.", "Monarchy: ruled by a king; the king collected taxes and kept an army.\nGana: ruled by a group of leaders who took decisions together; the Vajji sangha of Vaishali is an example.", "short"),
      W(2, "How were the Vajji people governed?", "The Vajji sangha, with Vaishali as its centre, was ruled by a group of leaders who took decisions together.", "short"),
      W(2, "Why did kings keep armies and forts?", "Armies defended and expanded the state.\nForts protected the capitals.", "short"),
      W(3, "How did iron tools help towns to grow?", "Iron tools helped farmers to clear land and grow more food.\nMore food supported more people.\nThis helped towns and trade to grow.", "short"),
      W(4, "Explain why Magadha became the most powerful state.", "It had fertile land, iron ore mines, forests with elephants and river routes for trade.\nRulers such as Bimbisara and Ajatashatru expanded it.\nIts capital was first Rajagriha and later Pataliputra.", "long"),
      W(5, "Describe the rise of cities and states from the 6th century BCE.", "From about the 6th century BCE, towns grew in the Ganga plains, helped by farming, iron tools and trade.\nLarger states called Mahajanapadas emerged; texts mention sixteen of them.\nMost were monarchies, while some ganas like the Vajji sangha were ruled by groups of leaders.\nKings collected taxes and kept armies, and punch-marked coins made trade easier.\nMagadha became the most powerful state.", "long"),
      W(4, "Case study: A trader from a town in the Ganga plains wants to sell grain. Buyers in a faraway town will not accept grain but will accept small silver pieces with marks on them. The trader's ruler collects taxes in these pieces.\n(i) What are the silver pieces called?\n(ii) What problem do they solve?\n(iii) Why does the ruler collect taxes?", "(i) Punch-marked coins.\n(ii) They solve the problem of barter, since coins are accepted by many people.\n(iii) To pay for the army, forts and government.", "case"),
    ]
  },
  "the-rise-of-empires": {
    mcq: [
      M(1, "The Mauryan empire was divided into", "provinces", ["islands", "oceans", "deserts"], "The empire was divided into provinces governed by officials."),
      M(1, "Taxes on farming and trade in the Mauryan empire paid for", "the army and the government", ["rock paintings", "private temples only", "foreign envoys' homes"], "Taxes paid for the army and the government."),
      M(1, "Ashoka's dhamma asked people to be kind to", "all living beings", ["only the royal family", "only the soldiers", "only the traders"], "Dhamma included kindness, tolerance, respect for elders and care for all living beings."),
      M(1, "An edict is", "an official order or message", ["a silver coin with marks on it", "a fort that guarded the capital", "a book on statecraft and politics"], "Ashoka's edicts were messages carved on rocks and pillars."),
      M(1, "Roads and rivers in the Mauryan empire helped", "trade", ["the Kalinga war", "the Rigveda", "the Stone Age"], "Roads and rivers connected the empire and helped trade."),
      M(1, "Which of these is a Mauryan practice?", "Appointing officials for provinces", ["Electing a council in each village", "Using paper money for large payments", "Making payments through mobile apps"], "Officials were appointed by the king to govern provinces."),
      M(2, "In the Mauryan empire, provincial officials were", "appointed by the king", ["elected by the people", "chosen by a lottery", "chosen by foreign envoys"], "The empire was divided into provinces governed by officials appointed by the king."),
      M(2, "The Mauryan kings kept spies so that they could", "know what happened in the empire", ["write the hymns of the Vedas", "make punch-marked coins in mints", "carve edicts upon rocks and pillars"], "A large army and spies helped the king rule the large empire."),
      M(2, "A king sees great suffering after a war and decides to rule by kindness. This best matches", "Ashoka after the Kalinga war", ["Chandragupta at Pataliputra", "Megasthenes at court", "Bimbisara of Magadha"], "After the Kalinga war Ashoka felt great sorrow and gave up conquest by war."),
      M(2, "Which of these happened between the founding of the Mauryan empire (about 321 BCE) and the Kalinga war (about 261 BCE)?", "Ashoka became emperor (about 268 BCE)", ["The Gupta empire began", "The Battle of Tarain", "The first passenger train"], "Ashoka became emperor about 268 BCE, before the Kalinga war."),
      M(2, "How many years passed from the founding of the empire (about 321 BCE) to the Kalinga war (about 261 BCE)?", "About 60 years", ["About 6 years", "About 160 years", "About 600 years"], "321 − 261 = 60 years."),
      M(2, "Ashoka had his edicts placed on rocks and pillars so that", "many people could see them", ["only the king could read them", "they would be buried", "they would be sold abroad"], "Public rocks and pillars let many people read or hear his messages."),
      M(2, "Ashoka became emperor about 268 BCE, which is in the", "3rd century BCE", ["4th century BCE", "3rd century CE", "5th century BCE"], "268 BCE falls between 300 BCE and 201 BCE, the 3rd century BCE."),
      M(2, "Chandragupta Maurya founded the empire about 321 BCE, which is in the", "4th century BCE", ["3rd century BCE", "4th century CE", "6th century BCE"], "321 BCE falls in the 4th century BCE."),
      M(2, "Which is the correct order of these events of the Mauryan period?", "empire founded, Ashoka becomes emperor, Kalinga war", ["Kalinga war, empire founded, Ashoka becomes emperor", "Ashoka becomes emperor, empire founded, Kalinga war", "empire founded, Kalinga war, Ashoka becomes emperor"], "About 321 BCE, then about 268 BCE, then about 261 BCE."),
      M(1, "Ashoka's dhamma asked people to be tolerant of", "others' beliefs", ["no one at all", "only the army", "only the farmers"], "Dhamma included tolerance, kindness and respect for elders."),
      M(2, "Today the government also collects taxes to pay for services. Which Mauryan practice is similar?", "Taxes paying for army and government", ["Edicts written in the Brahmi script", "Spies working at the royal court", "The Lion Capital as national emblem"], "Taxes on farming and trade paid for the army and government."),
      M(1, "Edicts carved on stone are a kind of", "inscription", ["coin", "seal", "oral source"], "An inscription is writing carved on stone or metal."),
      M(3, "Which account would give an outsider's view of the Mauryan court?", "Megasthenes' writings", ["Ashoka's rock edicts", "A coin of Chandragupta", "The Lion Capital emblem"], "Megasthenes was a Greek envoy at Chandragupta's court and wrote about India."),
      M(3, "A student says 'After Kalinga, Ashoka conquered even more lands by war'. What is wrong?", "He gave up conquest by war", ["Kalinga was a kingdom of Greece", "He never fought in any battle", "He had died before Kalinga was fought"], "After the bloody Kalinga war he gave up conquest by war."),
      M(2, "Which pair is mismatched?", "Megasthenes – a Mauryan minister", ["Chanakya – Chandragupta's minister", "Ashoka – promoted dhamma", "Chandragupta – founder of the empire"], "Megasthenes was a Greek envoy, not a minister."),
      M(3, "Which statement is correct?", "Chandragupta founded it; Ashoka gave up war", ["Ashoka founded it; Chandragupta gave up war", "Both gave up war after the Kalinga war", "Neither of them used Pataliputra as capital"], "Chandragupta founded the empire; Ashoka changed after the Kalinga war."),
      M(2, "A large army, spies and appointed officials suggest the Mauryan king wished to", "control a large empire", ["give up ruling", "let every village rule itself", "end all trade"], "These were tools of administration for a vast empire."),
      M(3, "Why was dhamma important after a bloody war?", "It put kindness in place of conquest", ["It began a fresh war on neighbours", "It cancelled all the laws of the empire", "It ended all farming in the provinces"], "Ashoka promoted kindness, tolerance and care for all living beings."),
      M(3, "Why are Ashoka's edicts reliable sources for his policy?", "They are his own messages carved in his time", ["They were written centuries later", "They were written by foreigners", "They were never public"], "They are written records from Ashoka's own time."),
    ],
    written: [
      W(1, "Who was Chanakya?", "Chanakya (Kautilya) was the minister who helped Chandragupta Maurya. He is traditionally linked with the Arthashastra.", "short"),
      W(2, "Write two reasons why historians value Megasthenes' account.", "He was a Greek envoy who lived at Chandragupta's court.\nHe wrote about India as an outsider, so his account gives a description of the Mauryan court and country.", "short"),
      W(2, "How was the Mauryan empire administered?", "It was divided into provinces governed by officials appointed by the king.\nThe king had a large army and spies.", "short"),
      W(2, "Why were taxes important to the Mauryan empire?", "Taxes on farming and trade paid for the army and the government.", "short"),
      W(2, "What was the Kalinga war? What was its effect on Ashoka?", "It was a bloody war fought about 261 BCE.\nAshoka felt great sorrow and gave up conquest by war.", "short"),
      W(2, "Name four ideas of Ashoka's dhamma.", "Kindness, tolerance, respect for elders and care for all living beings.", "short"),
      W(3, "What is the importance of the Lion Capital at Sarnath today?", "The Lion Capital at Sarnath is Ashoka's pillar.\nIt is now India's national emblem.\nIt reminds us of Ashoka's message of peace.", "short"),
      W(4, "Describe the founding and administration of the Mauryan empire.", "Chandragupta Maurya founded the empire in the late 4th century BCE (about 321 BCE) with its capital at Pataliputra.\nHe was helped by his minister Chanakya.\nThe empire had provinces ruled by appointed officials, a large army and spies.\nTaxes paid for the army and government, and roads and rivers helped trade.", "long"),
      W(5, "Describe Ashoka and his policy of dhamma.", "Ashoka became emperor about 268 BCE.\nAfter the bloody Kalinga war (about 261 BCE) he felt great sorrow and gave up conquest by war.\nHe promoted dhamma: kindness, tolerance, respect for elders and care for all living beings.\nHe had his messages carved on rocks and pillars, mostly in Brahmi.\nThe Lion Capital at Sarnath is now India's national emblem.", "long"),
      W(4, "Case study: A foreign visitor to Pataliputra writes about the roads, the king's army, spies and officials. In a faraway village, villagers read a message carved on a pillar telling them to be kind to all living beings.\n(i) Who was the Greek envoy who wrote about India?\n(ii) What is the carved message called?\n(iii) Which ruler wanted people to follow this teaching?", "(i) Megasthenes.\n(ii) An edict.\n(iii) Ashoka.", "case"),
    ]
  },
  "the-age-of-reorganisation": {
    mcq: [
      M(1, "A dynasty is", "a line of rulers from one family", ["a type of trade route in the north", "a kind of coin used in the south", "a poem written in the Sangam age"], "The Satavahanas are an example of a dynasty."),
      M(1, "Port towns on the coasts grew rich through", "trade", ["hunting", "Stone Age tools", "rock painting"], "Trade by sea made port towns rich."),
      M(1, "The Cheras, Cholas and Pandyas ruled in the", "far south", ["far north", "north-west", "north-east"], "They were the kingdoms of the far south in the Sangam age."),
      M(1, "Which of these was a land trade route linking India with other regions?", "The Silk Route", ["The Palk Strait", "The Ganga", "The Thar"], "The Silk Route was a network of land routes linking China, Central Asia and the West."),
      M(1, "Which of these travelled along trade routes besides goods?", "Ideas, religions and art", ["Only soldiers and kings", "Only farmers and their cattle", "Nothing except the goods"], "Trade spread ideas, religions and art between regions."),
      M(1, "Which Indian goods were in demand abroad?", "Spices, cotton cloth and pearls", ["Printed books and machine cloth", "Steel ships and railway engines", "Paper money and plastic goods"], "Spices, cotton cloth and pearls were in demand."),
      M(1, "Early Tamil poems of the ancient south belong to the", "Sangam age", ["Gupta age", "Harappan age", "Stone Age"], "Sangam literature tells about the early kingdoms of the south."),
      M(1, "After the Mauryas, the Shungas ruled in the", "north", ["far south", "Deccan plateau", "islands"], "The Shungas were a regional kingdom in the north."),
      M(2, "Which dynasty ruled furthest to the south?", "The Pandyas", ["The Satavahanas", "The Shungas", "The Kushanas"], "The Pandyas ruled in the far south, while the Satavahanas ruled the Deccan."),
      M(2, "Which row is WRONG?", "Satavahanas – far south", ["Shungas – north", "Cholas – far south", "Kushanas – parts of north India"], "The Satavahanas ruled much of the Deccan, not the far south."),
      M(2, "Which of these was NOT a region linked to India by trade in this period?", "The Americas", ["Central Asia", "China", "The Roman world"], "Trade links ran to Central Asia, China and the Roman world."),
      M(2, "How did port towns' trade help the kings?", "It brought wealth and taxes", ["It ended all farming", "It stopped other kingdoms", "It lowered every tax"], "Trade made port towns rich and helped kingdoms grow."),
      M(2, "Why was the trade network called the 'Silk Route'?", "Silk was a famous good carried on it", ["The whole road was paved with silk", "It was a river carrying silk boats", "It was built by silk workers only"], "The Silk Route linked China, Central Asia and the West."),
      M(2, "Which of these is a literary source for the far south?", "Sangam poems", ["Ashoka's rock edicts", "The Prayag Pillar", "The Delhi iron pillar"], "Early Tamil literature of the Sangam age tells about the Cheras, Cholas and Pandyas."),
      M(2, "Which order of these two is correct?", "Mauryas, then Shungas in the north", ["Shungas, then Mauryas", "Kushanas, then Mauryas", "Satavahanas, then Mauryas"], "The Shungas rose in the north after the Mauryan empire weakened."),
      M(2, "Which two groups from Central Asia settled in parts of north India?", "Shakas and Kushanas", ["Cheras and Pandyas", "Shungas and Mauryas", "Satavahanas and Cholas"], "The Shakas and Kushanas came from Central Asia."),
      M(2, "Which sentence about the Deccan is correct?", "The Satavahanas ruled much of it", ["The Kushanas ruled all of it", "It was in the far north", "It had no dynasty"], "The Satavahanas ruled much of the Deccan."),
      M(2, "Which of these was a Satavahana king?", "Gautamiputra Satakarni", ["Kanishka of the Kushanas", "Samudragupta of the Guptas", "Bimbisara of Magadha"], "Gautamiputra Satakarni was among the well-known Satavahana kings."),
      M(2, "Power was divided among many regional rulers, yet regions stayed connected through", "trade routes", ["a single capital", "one emperor", "one language alone"], "Land and sea trade linked regions and spread goods and ideas."),
      M(3, "A hoard of Roman coins is found at a south Indian port. This suggests that", "India traded with the Roman world", ["Rome ruled the south", "the port had no trade", "India traded only with Nepal"], "Sea trade linked India with the Roman world."),
      M(3, "Arrange from north to south: Shungas, Satavahanas, Pandyas.", "Shungas, Satavahanas, Pandyas", ["Pandyas, Satavahanas, Shungas", "Satavahanas, Shungas, Pandyas", "Shungas, Pandyas, Satavahanas"], "The Shungas were in the north, the Satavahanas in the Deccan and the Pandyas in the far south."),
      M(3, "Which statement is correct?", "Kanishka was a Kushana; Gautamiputra a Satavahana", ["Kanishka was a Chola king; Gautamiputra a Shunga", "Kanishka was a Pandya king; Gautamiputra a Kushana", "Both were kings of the Chera kingdom in the south"], "Kanishka belonged to the Kushanas and Gautamiputra Satakarni to the Satavahanas."),
      M(2, "A Roman trader wishes to buy pearls. He will most likely visit", "a port town of the south", ["the Thar Desert", "the Himalayas", "a hill village"], "Port towns grew rich through the trade in pearls, spices and cotton cloth."),
      M(2, "Indian pearls and spices reached the Roman world mainly through", "trade routes by land and sea", ["royal orders only", "school tours", "tax collectors"], "Trade by land (the Silk Route) and by sea linked India with the Roman world."),
      M(3, "Which is the best reason why trade helped spread religions?", "Traders carried ideas to new lands", ["Religions need silk to spread widely", "Trade routes were closed to travellers", "Kings banned religions at the ports"], "Trade spread ideas, religions and art between regions."),
      M(3, "Which description of the period after the Mauryas is correct?", "Many regional kings and outside groups ruled", ["One single emperor ruled the whole of India", "Rule was in the hands of the army alone", "Only republics existed in every region"], "After the Mauryan empire weakened, several regional kingdoms rose and power became divided."),
    ],
    written: [
      W(1, "Name the three kingdoms of the far south in the Sangam age.", "The Cheras, Cholas and Pandyas.", "short"),
      W(1, "What is a dynasty?", "A dynasty is a line of rulers from the same family.", "short"),
      W(2, "Who were the Shakas and Kushanas?", "They were groups from Central Asia who settled in parts of north India.\nKanishka was a famous Kushana ruler.", "short"),
      W(2, "Which dynasty ruled the Deccan? Name one of its kings.", "The Satavahanas ruled much of the Deccan.\nGautamiputra Satakarni was a well-known king.", "short"),
      W(2, "What was the Silk Route?", "It was a network of trade routes linking China, Central Asia and the West.", "short"),
      W(2, "Name three Indian goods that were in demand abroad.", "Spices, cotton cloth and pearls.", "short"),
      W(3, "How did trade spread ideas as well as goods?", "Traders and travellers moved along land and sea routes.\nThey carried religions, art and ideas to new places.\nSo trade linked different regions.", "short"),
      W(4, "Describe the political situation of India after the Mauryas.", "After the Mauryan empire weakened, regional kingdoms rose, such as the Shungas in the north.\nShakas and Kushanas from Central Asia settled in north India.\nThe Satavahanas ruled the Deccan, and the Cheras, Cholas and Pandyas ruled the far south.\nPower was divided among many regional rulers.", "long"),
      W(5, "How did the port towns on the coasts become rich, and how did this help the kingdoms?", "Trade routes by sea linked India with the Roman world and other lands.\nIndian goods such as spices, cotton cloth and pearls were in demand abroad.\nPort towns grew rich through this trade, which gave their kings wealth.\nThe wealth helped the kingdoms grow.", "long"),
      W(4, "Case study: A Roman merchant sails to a south Indian port and buys pearls and cotton cloth. A poem from the Sangam age praises the king of the land. A Kushana ruler's coin is found in a northern town.\n(i) Which trade link does the merchant's visit show?\n(ii) Name one kingdom of the far south.\n(iii) Which Kushana ruler is named in the lesson?", "(i) Trade between India and the Roman world by sea.\n(ii) The Cheras, Cholas or Pandyas.\n(iii) Kanishka.", "case"),
    ]
  },
  "the-gupta-era": {
    mcq: [
      M(1, "Who was the first Gupta ruler in the lesson, with whom the empire began?", "Chandragupta I", ["Chandragupta II", "Chandragupta Maurya", "Harishena"], "The Gupta empire began around 320 CE with Chandragupta I."),
      M(1, "Nalanda was a famous centre of", "learning", ["war", "shipbuilding", "salt making"], "Nalanda was a famed centre of learning."),
      M(1, "The study of the sun, moon, stars and planets is", "astronomy", ["archaeology", "geography", "economics"], "Aryabhata and Varahamihira wrote on astronomy."),
      M(1, "The Prayag Pillar stands in the city now called", "Prayagraj", ["Pataliputra", "Sarnath", "Mohenjo-daro"], "It is also known as the Allahabad Pillar."),
      M(1, "Fa-Xian came to India as a", "pilgrim", ["soldier", "king", "trader of silk"], "Fa-Xian was a Chinese monk who travelled as a pilgrim."),
      M(1, "The time of Chandragupta II is described as one of", "peace and prosperity", ["war and famine", "invasion", "exile"], "Chandragupta II (Vikramaditya) ruled during a time of peace and prosperity."),
      M(1, "Abhijnanashakuntalam is a", "play", ["temple", "pillar", "coin"], "It is a work of the poet and playwright Kalidasa."),
      M(2, "Aryabhata was born in 476 CE, which is in the", "5th century CE", ["4th century CE", "6th century CE", "5th century BCE"], "476 falls between 401 and 500, so it is the 5th century CE."),
      M(2, "Which empire came later in time?", "The Gupta empire", ["The Mauryan empire", "The Magadha of Bimbisara", "The Harappan civilisation"], "The Harappan civilisation was earliest, then Magadha, the Mauryas and then the Guptas."),
      M(2, "The Mauryan empire began about 321 BCE and the Gupta empire about 320 CE. About how many years apart?", "About 640 years", ["About 1 year", "About 64 years", "About 6,400 years"], "321 + 320 = 641 years, since one is BCE and the other CE."),
      M(2, "Which pair is mismatched?", "Harishena – the poet of Abhijnanashakuntalam", ["Kalidasa – a poet and playwright", "Fa-Xian – a Chinese monk", "Varahamihira – astronomy"], "Harishena wrote the Prayag Pillar inscription; Kalidasa wrote Abhijnanashakuntalam."),
      M(1, "In the number 305 in the place-value system, the digit 3 stands for", "300", ["3", "30", "3,000"], "The value of a digit depends on its position."),
      M(2, "In the number 205, the zero shows that there are", "no tens", ["no hundreds", "no ones", "no digits"], "Zero holds a place so that the other digits keep their positions."),
      M(2, "Which of these shows Gupta skill in building and art?", "Temples and sculptures", ["Punch-marked coins", "Rock edicts of Ashoka", "Harappan seals"], "Gupta temples, sculptures and cave paintings show great skill."),
      M(2, "The Prayag Pillar inscription is a source that is", "carved writing on stone", ["an oral story", "a folk song", "a painting"], "An inscription is writing carved on stone or metal."),
      M(2, "Abhijnanashakuntalam is an example of a", "literary source", ["archaeological find", "oral memory", "coin"], "Literary sources are written texts."),
      M(2, "Which city was the capital of both the Mauryas and the Guptas?", "Pataliputra", ["Kannauj", "Badami", "Kanchipuram"], "Pataliputra was the capital of both empires."),
      M(2, "Ashoka (3rd century BCE) and Samudragupta (4th century CE): who came earlier?", "Ashoka", ["Samudragupta", "They were contemporaries", "It cannot be said"], "A BCE century is earlier than any CE century."),
      M(2, "Which set shows Gupta-age creativity?", "Aryabhata's astronomy, Kalidasa's plays and Ajanta", ["Harappan seals, the Great Bath and granaries", "Rock edicts, pillars and the Brahmi script", "Sangam poems, the Silk Route and port towns"], "The period saw advances in science, mathematics, literature and art."),
      M(2, "Which two scholars of this era wrote on astronomy?", "Aryabhata and Varahamihira", ["Kalidasa and Harishena", "Fa-Xian and Samudragupta", "Charaka and Sushruta"], "Aryabhata and Varahamihira wrote on astronomy."),
      M(3, "Which of these came FIRST in time?", "Chandragupta I's rule", ["Aryabhata's birth in 476 CE", "Fa-Xian's visit in Chandragupta II's time", "Chandragupta II's rule"], "Chandragupta I began the Gupta empire about 320 CE, before the others."),
      M(3, "A pillar at Prayagraj praises a king's victories. Who is the king, and who wrote it?", "Samudragupta, written by Harishena", ["Chandragupta II, written by Kalidasa", "Ashoka, written by Fa-Xian", "Chandragupta I, written by Aryabhata"], "The Prayag Pillar inscription of Harishena records Samudragupta's deeds."),
      M(3, "Which order of Gupta rulers is correct?", "Chandragupta I, Samudragupta, Chandragupta II", ["Chandragupta II, Chandragupta I, Samudragupta", "Samudragupta, Chandragupta II, Chandragupta I", "Chandragupta I, Chandragupta II, Samudragupta"], "Chandragupta I began the empire; Samudragupta expanded it; Chandragupta II ruled in peace."),
      M(3, "Which combination shows both science and art of the Gupta age?", "Aryabhata and Ajanta", ["Megasthenes and Sarnath", "Harishena and Brahmi", "Fa-Xian and Silk Route"], "Aryabhata worked in mathematics and astronomy; Ajanta has cave paintings."),
      M(3, "A Chinese monk wrote about Indian life in the time of Chandragupta II. Why is this useful to historians?", "It gives an outsider's account of that age", ["It proves that Chinese kings ruled India", "It replaced all the inscriptions of the age", "It was written by Samudragupta himself"], "Fa-Xian's visit gives a foreign visitor's account."),
    ],
    written: [
      W(1, "Who was Kalidasa?", "Kalidasa was a famous poet and playwright. He wrote works such as Abhijnanashakuntalam.", "short"),
      W(1, "Name the capital of the Gupta empire.", "The capital was Pataliputra.", "short"),
      W(2, "Who was Fa-Xian? When did he visit India?", "Fa-Xian was a Chinese monk.\nHe visited India during the time of Chandragupta II.", "short"),
      W(2, "What is the place-value system? Why is zero important in it?", "In a place-value system the value of a digit depends on its position.\nZero holds a place, so numbers can be written and calculated easily.", "short"),
      W(2, "Why is the Prayag Pillar inscription important?", "It records the deeds of Samudragupta.\nIt was written by Harishena and is a valuable source for historians.", "short"),
      W(2, "Name two Gupta-age scholars and say what each wrote about.", "Aryabhata wrote on mathematics and astronomy.\nVarahamihira wrote on astronomy and other sciences.", "short"),
      W(2, "How did Nalanda help in spreading knowledge?", "Nalanda was a famed centre of learning.\nScholars and students gathered there to study.", "short"),
      W(4, "Write about Samudragupta and the source from which we know about his deeds.", "Samudragupta expanded the Gupta empire widely.\nHis deeds are recorded in the Prayag (Allahabad) Pillar inscription written by Harishena.\nThe inscription is a valuable written record for historians.", "long"),
      W(5, "Why is the Gupta period called an age of tireless creativity? Give examples from science, art and metal work.", "In science, Aryabhata wrote on mathematics and astronomy and explained that the Earth rotates; the decimal place-value system and zero developed around this time; Varahamihira wrote on astronomy.\nIn learning, Nalanda was a famed centre.\nIn literature, Kalidasa wrote Abhijnanashakuntalam.\nIn art, Gupta temples, sculptures and Ajanta paintings show great skill.\nThe Delhi iron pillar shows advanced metal working.", "long"),
      W(4, "Case study: A teacher shows a picture of the Delhi iron pillar that has hardly rusted. She also reads a verse from a play by Kalidasa and tells the class about a Chinese monk who visited in Chandragupta II's reign.\n(i) What does the iron pillar show?\n(ii) Name the play by Kalidasa mentioned in the lesson.\n(iii) Name the Chinese monk.", "(i) Advanced metal working.\n(ii) Abhijnanashakuntalam.\n(iii) Fa-Xian.", "case"),
    ]
  },
  "how-the-land-becomes-sacred": {
    mcq: [
      M(1, "Which river is named in the lesson as a river treated as sacred?", "The Ganga", ["The Palk", "The Thar", "The Deccan"], "People in India have long treated rivers such as the Ganga as sacred."),
      M(1, "A tirtha is", "a holy place, often by a river", ["a coin used by early traders", "a season for sowing the crops", "a dance form of the classical type"], "Tirtha yatra means a pilgrimage to a holy place."),
      M(1, "A shrine is", "a holy place where people pray", ["a market where cloth is sold daily", "a painting made on a rock shelter", "an office where taxes are collected"], "A shrine is a holy place, often a small temple or tomb."),
      M(1, "In how many cities is the Kumbh Mela held, according to the lesson?", "Four", ["Two", "Six", "Twelve"], "Prayagraj, Haridwar, Ujjain and Nashik."),
      M(1, "'Tirtha yatra' means", "pilgrimage", ["trade fair", "tax collection", "farming season"], "A pilgrimage is a journey to a holy place."),
      M(1, "A common thread in many traditions of India is", "respect for nature", ["dislike of rivers", "fear of forests", "dislike of mountains"], "Rivers, mountains and forests are treated as sacred in many traditions."),
      M(1, "The Golden Temple is a holy place of", "Sikhs", ["Buddhists", "Jains", "Parsis"], "The Golden Temple at Amritsar is sacred to Sikhs."),
      M(1, "Which Char Dham place lies in the far south?", "Rameswaram", ["Badrinath", "Dwarka", "Puri"], "Rameswaram is the southern dham."),
      M(2, "Which Char Dham place lies on the western coast?", "Dwarka", ["Puri", "Badrinath", "Rameswaram"], "Dwarka is in the west; Puri is in the east."),
      M(2, "Which city is NOT a site of the Kumbh Mela?", "Amritsar", ["Prayagraj", "Haridwar", "Ujjain"], "The Kumbh Mela is held at Prayagraj, Haridwar, Ujjain and Nashik."),
      M(2, "Mosques and dargahs are visited by pilgrims of", "Islam", ["Buddhism", "Jainism", "Sikhism"], "India has holy places of many faiths, including mosques and dargahs."),
      M(2, "Sacred groves help the environment by", "protecting plants and animals", ["clearing the forest for new fields", "stopping all the rain in the area", "turning the land into a desert"], "Because they are protected, plants and animals survive there."),
      M(2, "A stall near a shrine earns ₹5,000 on festival days and ₹800 on other days. This shows that pilgrimage", "supports local livelihoods", ["ends all trade", "stops travel", "harms every shopkeeper"], "Pilgrimage supports trade, crafts, food and local livelihoods."),
      M(2, "Which of these gains from pilgrims coming to a town?", "Shopkeepers and craftspeople", ["Only the soldiers of the king", "Only the officers of the tax office", "Only the kings who visit the town"], "Pilgrimage supports trade, crafts and food."),
      M(2, "Pilgrim routes help to", "link different regions of the country", ["close the borders between the states", "stop people from travelling at all", "divide the country into separate parts"], "Pilgrim routes link regions, and pilgrimage brings people of different regions together."),
      M(2, "Jain tirthas are holy places of", "Jains", ["Parsis", "Christians", "Sikhs"], "The lesson lists Jain tirthas among the holy places of many faiths."),
      M(2, "Which two cities are both sites of the Kumbh Mela?", "Haridwar and Ujjain", ["Haridwar and Puri", "Ujjain and Dwarka", "Nashik and Amritsar"], "Haridwar and Ujjain are among the four Kumbh cities."),
      M(2, "A sacred grove is usually protected by", "the local community", ["the Union government only", "a foreign army", "no one"], "Local communities protect sacred groves because of religious belief."),
      M(2, "Which behaviour is respectful at a sacred river?", "Keeping the water and banks clean", ["Throwing waste into the flowing water", "Playing very loud music on the banks", "Cutting trees along the river banks"], "Respect for holy places includes keeping them clean."),
      M(2, "Which faith's holy places are Bodh Gaya and Sarnath?", "Buddhism", ["Sikhism", "Islam", "Jainism"], "Bodh Gaya and Sarnath are sacred to Buddhists."),
      M(3, "Ashoka's Lion Capital comes from a site that is also sacred to Buddhists. Which?", "Sarnath", ["Puri", "Haridwar", "Rameswaram"], "The Lion Capital of Ashoka at Sarnath is now India's national emblem, and Sarnath is a Buddhist holy place."),
      M(3, "Which pair shows the north–south range of the Char Dham?", "Badrinath in the north and Rameswaram in the south", ["Dwarka in the north and Puri in the south", "Puri in the north and Badrinath in the south", "Rameswaram in the north and Dwarka in the south"], "The four dhams lie in the north, west, east and south."),
      M(3, "Why might villagers protect a grove for centuries even without a law?", "Their belief makes the grove sacred", ["A king pays them a big salary for it", "Cutting trees there is a source of income", "The government forces them every year"], "Sacred groves are protected by communities because of religious belief."),
      M(3, "Which Char Dham pair lies furthest apart from each other?", "Badrinath and Rameswaram", ["Dwarka and Puri", "Badrinath and Dwarka", "Puri and Rameswaram"], "Badrinath is in the far north and Rameswaram in the far south."),
      M(3, "Which statement is correct?", "Pilgrimage helps livelihoods and needs clean holy places", ["Pilgrimage has nothing to do with trade or crafts", "Holy places in India belong to one single faith", "Only rivers, and nothing else, are held sacred"], "Pilgrimage supports livelihoods and brings people together; respect means caring for the places too."),
    ],
    written: [
      W(2, "Name two things in nature that people in India treat as sacred.", "Rivers such as the Ganga.\nMountains and forests (sacred groves).", "short"),
      W(1, "Name the four Char Dham.", "Badrinath, Dwarka, Puri and Rameswaram.", "short"),
      W(2, "Where is the Kumbh Mela held?", "At Prayagraj, Haridwar, Ujjain and Nashik.", "short"),
      W(2, "Name two holy places of other faiths in India.", "Bodh Gaya and Sarnath for Buddhists.\nThe Golden Temple at Amritsar for Sikhs. (Jain tirthas, mosques, dargahs and churches are also visited.)", "short"),
      W(2, "Why do sacred groves often remain rich in plants and animals?", "The community protects the forest because of religious belief.\nTrees are not cut and animals are not hunted there.", "short"),
      W(2, "Name two kinds of work that gain when pilgrims visit a holy town.", "Shopkeepers selling food and goods.\nCraftspeople selling crafts. (Boatmen and guides also gain.)", "short"),
      W(3, "How does pilgrimage bring people of different regions together?", "Pilgrim routes link regions of the country.\nPeople from many places meet at holy sites such as the Kumbh Mela.\nThey share customs, food and ideas.", "short"),
      W(4, "Explain how rivers, mountains and forests came to be seen as sacred in India.", "People have long treated rivers such as the Ganga, mountains and forests as sacred.\nRespect for nature is a common thread in many traditions.\nSacred groves are protected by communities, which helps protect plants and animals.", "long"),
      W(5, "Describe pilgrimage in India: its meaning, examples and benefits.", "A pilgrimage (tirtha yatra) is a journey to a holy place.\nExamples are the Char Dham (Badrinath, Dwarka, Puri and Rameswaram), the twelve Jyotirlingas and the Kumbh Mela at Prayagraj, Haridwar, Ujjain and Nashik.\nHoly places of many faiths include Bodh Gaya, Sarnath and the Golden Temple.\nPilgrimage supports trade, crafts, food and local livelihoods, and brings people of different regions together.", "long"),
      W(4, "Case study: Every year a river town hosts thousands of pilgrims. Shopkeepers sell flowers and sweets, boatmen earn from rides, and potters sell clay lamps. Residents also guard a sacred grove near the river.\n(i) What name is given to such a journey to a holy place?\n(ii) Give one way local people gain.\n(iii) What do we call the protected forest?", "(i) A pilgrimage.\n(ii) Shopkeepers, boatmen and potters earn an income.\n(iii) A sacred grove.", "case"),
    ]
  },
  "from-the-rulers-to-the-ruled": {
    mcq: [
      M(1, "Which of these services is provided by governments?", "Roads, schools and hospitals", ["Rainfall and sunshine", "Rivers and mountains", "Festivals and fairs"], "A government makes laws, keeps order, protects people and provides services like roads, schools and hospitals."),
      M(1, "Governments in India work at the local, state and", "national level", ["village level only", "school level", "ocean level"], "Governments work at local, state and national levels."),
      M(1, "The way a country is ruled is called its", "form of government", ["climate of the region", "currency of the nation", "boundary of the territory"], "Monarchy, dictatorship, oligarchy and democracy are forms of government."),
      M(1, "In a democracy, the power to choose rulers lies with the", "people", ["king", "army chief", "one rich family"], "In a democracy the people choose their rulers."),
      M(1, "A free press is a sign of a", "healthy democracy", ["monarchy", "dictatorship", "oligarchy"], "Free and fair elections, equal rights and a free press show a healthy democracy."),
      M(1, "In a monarchy, the ruler is usually chosen by", "birth", ["election", "lottery", "a vote of citizens"], "A king or queen rules, often by birth."),
      M(1, "A person turns 18 years old today. Which new right does she gain in India?", "To vote in elections", ["To become the President", "To make laws herself", "To collect taxes"], "Every citizen aged 18 or above can vote."),
      M(2, "Country A has a king who inherits the throne; B has one ruler who holds power without consent; C has a small group of rulers; D lets citizens choose rulers. Which is a democracy?", "D", ["A", "B", "C"], "In a democracy, the people have the power to choose their rulers."),
      M(2, "Country A has a king who inherits the throne; B has one ruler who holds power without consent; C has a small group of rulers; D lets citizens choose rulers. Which is a dictatorship?", "B", ["A", "C", "D"], "In a dictatorship, one person holds power without the people's consent."),
      M(2, "Country A has a king who inherits the throne; B has one ruler who holds power without consent; C has a small group of rulers; D lets citizens choose rulers. Which is an oligarchy?", "C", ["A", "B", "D"], "In an oligarchy, a small group rules."),
      M(2, "A class elects one student to speak for them to the principal. This is closest to", "representative democracy", ["a monarchy by birth in a family", "a dictatorship of a single person", "an oligarchy of a few families"], "People elect a representative to decide for them."),
      M(2, "Everyone in a small hostel gathers to vote on the menu. This is closest to", "direct democracy", ["representative democracy", "monarchy", "dictatorship"], "Citizens decide the issue themselves."),
      M(2, "Which of these is NOT a sign of a healthy democracy?", "Newspapers cannot publish criticism", ["Elections are free and fair for all", "Citizens have equal rights by law", "The press is free to report news"], "A free press is a sign of a healthy democracy."),
      M(2, "Universal adult franchise means that votes are given regardless of", "religion, caste, gender or wealth", ["age and citizenship of the voter", "being able to read and write well", "owning land in the voter's name"], "Every citizen aged 18 or above can vote, regardless of religion, caste, gender or wealth."),
      M(2, "A village street light is broken. Which level of government is closest to dealing with it?", "Local government", ["The national government", "A foreign government", "The army"], "Local government deals with village matters."),
      M(2, "Which pair is correctly matched?", "Monarchy – rule by a king or queen", ["Oligarchy – rule by the people", "Dictatorship – rule by a vote", "Democracy – rule by birth"], "A monarchy has a king or queen as ruler."),
      M(2, "Which of these differs a democracy from a dictatorship?", "People choose their rulers", ["Laws are made for the country", "Taxes are collected from the people", "Roads and schools are built by it"], "In a democracy the people choose their rulers; in a dictatorship one person holds power without consent."),
      M(2, "A government's work includes", "keeping order and protecting people", ["making rivers flow in each season", "growing rain clouds over the fields", "changing the seasons of the year"], "A government makes laws, keeps order and protects people."),
      M(2, "Which statement about India is correct?", "India is a representative democracy", ["India is ruled by a hereditary king", "India is ruled by a small group", "India has no elections for its rulers"], "India follows universal adult franchise and elects representatives."),
      M(3, "A country holds elections but allows only one group to vote. Is it a healthy democracy?", "No, because voting is not equal for all", ["Yes, because elections are held", "Yes, because it has a king", "No, because it has no elections"], "Universal adult franchise needs every adult citizen to vote regardless of group."),
      M(3, "Why is direct democracy hard in a large country?", "Millions cannot meet to decide issues", ["People never like to cast their votes", "Representatives are not allowed at all", "Large countries have no cities to meet in"], "A large country needs representatives to decide on behalf of the people."),
      M(3, "Which country is most likely a dictatorship?", "One where a single leader rules unchecked", ["One with free elections and a free press", "One where villagers meet in a Gram Sabha", "One where all citizens have equal rights"], "In a dictatorship, one person holds power without the people's consent."),
      M(3, "Which row is a correct match of country feature and form of government?", "A king and his heirs rule – monarchy", ["A few families rule – democracy", "People vote and choose – oligarchy", "One leader without consent – monarchy"], "Monarchy rules by birth; oligarchy by a small group; dictatorship by one person."),
      M(1, "A 17-year-old and a 19-year-old both live in India. Who can vote in the election?", "Only the 19-year-old", ["Only the 17-year-old", "Both", "Neither"], "The minimum voting age is 18."),
      M(3, "Which two features are both found in a healthy democracy?", "Free and fair elections and equal rights", ["A single ruler and no elections", "A hereditary king and equal rights", "A small ruling group and a free press"], "Free and fair elections, equal rights and a free press are signs of a healthy democracy."),
      M(2, "In a representative democracy, representatives are", "answerable to the voters who elected them", ["placed above the laws of the country", "chosen by birth in a royal family", "fixed for ever without any election"], "People elect representatives and can choose differently at the next election."),
    ],
    written: [
      W(2, "Name three functions of a government.", "Making laws, keeping order and protecting people.\nProviding services such as roads, schools and hospitals.", "short"),
      W(1, "Name the four forms of government in the lesson.", "Monarchy, dictatorship, oligarchy and democracy.", "short"),
      W(2, "Why does India use representative democracy and not direct democracy?", "India has millions of people, so they cannot all meet to decide each issue.\nSo people elect representatives to decide for them.", "short"),
      W(2, "Who can vote in India? State the rule in your own words.", "Every citizen aged 18 or above can vote.\nThis holds regardless of religion, caste, gender or wealth.", "short"),
      W(2, "Give two signs of a healthy democracy.", "Any two: free and fair elections, equal rights, a free press.", "short"),
      W(2, "How is a dictatorship different from a monarchy?", "In a dictatorship one person holds power without the people's consent.\nIn a monarchy a king or queen rules, often by birth.", "short"),
      W(3, "Why do we need governments at different levels?", "A country is big, so local governments look after local needs.\nState governments look after the state.\nThe national government looks after the whole country.", "short"),
      W(4, "Explain the main forms of government.", "In a monarchy, a king or queen rules, often by birth.\nIn a dictatorship, one person holds power without the people's consent.\nIn an oligarchy, a small group rules.\nIn a democracy, the people have the power to choose their rulers.", "long"),
      W(5, "Describe India as a representative democracy. Include voting rights and signs of a healthy democracy.", "India is a representative democracy: people elect representatives to decide for them.\nIt follows universal adult franchise: every citizen aged 18 or above can vote regardless of religion, caste, gender or wealth.\nFree and fair elections, equal rights and a free press are signs of a healthy democracy.\nGovernment works at local, state and national levels.", "long"),
      W(4, "Case study: In Ria's school the class elects a monitor every month by secret ballot, and every child who has joined this term can vote. The principal says the students may also write their opinions in the school newsletter freely.\n(i) What type of democracy does the election resemble?\n(ii) Which feature of a healthy democracy is the newsletter?\n(iii) What is the voting rule in this class similar to?", "(i) Representative democracy: they elect one person to speak for them.\n(ii) A free press.\n(iii) Universal adult franchise: every eligible person has the right to vote.", "case"),
    ]
  },
  "the-constitution-of-india-an-introduction": {
    mcq: [
      M(1, "India's Constitution was adopted on", "26 November 1949", ["26 January 1950", "15 August 1947", "2 October 1948"], "It was adopted on 26 November 1949 and came into force on 26 January 1950."),
      M(1, "A constitution is the", "supreme set of rules for governing a country", ["history of a country", "list of its rivers", "map of its states"], "It sets out how the country is governed."),
      M(1, "Which of these is a Fundamental Right?", "Right against exploitation", ["Right to a free holiday", "Right to choose any ruler's throne", "Right to skip school"], "Fundamental Rights include equality, freedom and the right against exploitation."),
      M(1, "How many words does the Preamble use to describe India: sovereign, socialist, secular, democratic and republic?", "Five", ["Three", "Four", "Six"], "The five words are sovereign, socialist, secular, democratic and republic."),
      M(1, "Which word in the Preamble means that India is free from outside control?", "Sovereign", ["Secular", "Socialist", "Fraternity"], "Sovereign means having full power to rule itself."),
      M(1, "Protecting public property and the environment is a", "Fundamental Duty", ["Directive Principle", "Fundamental Right", "Preamble word"], "Fundamental Duties remind citizens of their responsibilities."),
      M(1, "Republic Day is celebrated on", "26 January", ["26 November", "15 August", "2 October"], "It marks the day the Constitution came into force."),
      M(2, "About how long was it between the adoption (26 Nov 1949) and the Constitution coming into force (26 Jan 1950)?", "Two months", ["Two days", "Two years", "Twenty years"], "From 26 November to 26 January is two months."),
      M(2, "Which pair is mismatched?", "Dr Rajendra Prasad – chair of the Drafting Committee", ["Constituent Assembly – drafted the Constitution", "Dr B. R. Ambedkar – chair of the Drafting Committee", "Preamble – states the goals"], "Dr Rajendra Prasad was President of the Constituent Assembly; Dr Ambedkar chaired the Drafting Committee."),
      M(1, "A country whose head of state is elected, not a hereditary monarch, is a", "republic", ["monarchy", "dynasty", "oligarchy"], "India is a republic."),
      M(2, "A factory makes young children work all day. Which right is being violated?", "Right against exploitation", ["Right to equality before the law", "Right to vote at 18", "Right to move house"], "Fundamental Rights protect people against exploitation."),
      M(2, "A speaker is stopped from sharing his opinion peacefully. Which Fundamental Right is affected?", "Freedom", ["Right against exploitation", "Duty to protect property", "Directive Principle"], "Freedom is one of the Fundamental Rights."),
      M(2, "Two students in the same class are treated differently because of their caste. Which value is being ignored?", "Equality", ["Fraternity only", "Republic", "Sovereignty"], "The Preamble aims to secure equality for all citizens."),
      M(2, "How many values does the Preamble name for securing for all citizens: justice, liberty, equality and fraternity?", "Four", ["Two", "Three", "Six"], "Justice, liberty, equality and fraternity are four."),
      M(2, "Fundamental Duties are meant for", "citizens", ["only the judges", "only the ministers", "only the army"], "Fundamental Duties remind citizens of their responsibilities."),
      M(2, "The Constitution was adopted in 1949 and came into force in 1950. How many calendar years separate the two?", "One year", ["Two years", "Ten years", "Zero years"], "1950 − 1949 = 1."),
      M(2, "Which is a Fundamental Duty of a student?", "Respecting the Constitution", ["Breaking public property", "Ignoring the environment", "Skipping school for pleasure"], "Duties include respecting the Constitution."),
      M(2, "Which statement about the Preamble is correct?", "It introduces the Constitution and its goals", ["It lists every law passed in the country", "It names each of the states of India", "It gives the rivers and mountains of India"], "The Preamble introduces the Constitution and states its goals."),
      M(2, "Which of these words describes India's government in the Preamble?", "Democratic", ["Hereditary", "Military", "Colonial"], "India is a sovereign, socialist, secular, democratic republic."),
      M(2, "Which sequence is in the correct date order?", "Adoption, Republic Day", ["Republic Day, adoption", "Both the same day", "Neither has a date"], "Adoption was on 26 November 1949 and Republic Day on 26 January 1950."),
      M(3, "Why do citizens have duties as well as rights?", "Rights work best when duties are done too", ["Duties are meant only for government officers", "Courts cannot protect rights without duties", "Rights are lost whenever someone votes"], "Duties remind citizens of their responsibilities to others and the nation."),
      M(2, "Which of these is NOT a value the Preamble aims to secure for all citizens?", "Monarchy", ["Justice", "Liberty", "Equality"], "The Preamble aims to secure justice, liberty, equality and fraternity."),
      M(3, "Which pair of values appear together in the Preamble's aims?", "Justice and liberty", ["Barter and trade", "Rent and tax", "Power and wealth"], "The Preamble aims to secure justice, liberty, equality and fraternity."),
      M(3, "A newspaper writes 'Every citizen must keep public places clean'. This is best linked to", "Fundamental Duties", ["Fundamental Rights", "Directive Principles only", "The Preamble's word republic"], "Fundamental Duties include protecting public property and the environment."),
      M(3, "Why is the Constitution called a 'supreme' law?", "All other laws must follow it", ["It is the oldest book in India", "A king alone wrote it", "It applies only to courts"], "It is the supreme set of rules by which the country is governed."),
      M(3, "Which person is correctly linked to the work of the Constituent Assembly?", "Dr Rajendra Prasad as President", ["Dr Ambedkar as President of India", "Dr Prasad as chair of the Drafting Committee", "No one led it"], "Dr Rajendra Prasad was President of the Constituent Assembly."),
    ],
    written: [
      W(1, "What is the Preamble?", "The Preamble is the introduction to the Constitution. It states the Constitution's aims and values.", "short"),
      W(1, "When was the Constitution adopted and when did it come into force?", "It was adopted on 26 November 1949.\nIt came into force on 26 January 1950.", "short"),
      W(2, "Name the four values the Preamble aims to secure for all citizens.", "Justice, liberty, equality and fraternity.", "short"),
      W(2, "Who were Dr Rajendra Prasad and Dr B. R. Ambedkar in the making of the Constitution?", "Dr Rajendra Prasad was President of the Constituent Assembly.\nDr B. R. Ambedkar chaired the Drafting Committee.", "short"),
      W(2, "What are Fundamental Rights? Give two examples.", "Fundamental Rights are basic rights guaranteed to citizens and protected by courts.\nExamples: equality, freedom, right against exploitation.", "short"),
      W(2, "What are Directive Principles?", "They are guidelines that help governments make policies for the welfare of people.", "short"),
      W(3, "Give three Fundamental Duties of citizens.", "Respecting the Constitution.\nProtecting public property.\nProtecting the environment.", "short"),
      W(4, "Explain how the Constitution of India was made.", "A constitution is the supreme set of rules for governing a country.\nIndia's Constitution was drafted by the Constituent Assembly, with Dr Rajendra Prasad as President.\nDr B. R. Ambedkar chaired the Drafting Committee.\nIt was adopted on 26 November 1949 and came into force on 26 January 1950, now celebrated as Republic Day.", "long"),
      W(5, "Describe the main features of the Constitution: the Preamble, Fundamental Rights, Directive Principles and Fundamental Duties.", "The Preamble introduces the Constitution and states its goals: India is sovereign, socialist, secular, democratic and a republic, and aims for justice, liberty, equality and fraternity.\nFundamental Rights protect citizens, such as equality, freedom and the right against exploitation, and courts can protect them.\nDirective Principles guide governments for the welfare of people.\nFundamental Duties remind citizens of their responsibilities.", "long"),
      W(4, "Case study: On 26 January a school holds a flag-hoisting ceremony. The teacher asks the children what the day marks. A student says the Constitution was adopted that day; another says it came into force that day.\n(i) Who is correct?\n(ii) What is this day called?\n(iii) Which part of the Constitution states its goals?", "(i) The second student; the Constitution came into force on 26 January 1950 (it was adopted on 26 November 1949).\n(ii) Republic Day.\n(iii) The Preamble.", "case"),
    ]
  },
  });
})();
